export const topics = [
  // DSA
  { id: 'dsa-complexity', trackId: 'dsa', title: 'Complexity without hand-waving', level: 'Foundation', minutes: 18, concept: 'Time complexity describes how an algorithm’s work grows with input size; space complexity describes the extra memory it needs. Big-O is an upper-bound growth description, not a stopwatch reading. Drop constants and lower-order terms only when describing asymptotic growth: 3n² + 5n + 8 becomes O(n²).', example: 'A loop over n items is O(n). Two independent nested loops are usually O(n²). Sorting n values with merge sort is O(n log n). A hash lookup is average O(1), but can degrade when collisions are pathological.', interview: 'State the input size first, count the dominant operation, then discuss best/average/worst case when they differ. Mention auxiliary space separately from input storage.', pitfalls: ['Calling every nested loop O(n²) without checking the loop bounds.', 'Treating average-case O(1) hash lookup as a hard worst-case guarantee.', 'Confusing O(n) with exactly n operations.'], checks: [{ question: 'What is the complexity of two consecutive loops, each running n times?', answer: 'O(n), because 2n simplifies to linear growth.' }, { question: 'What is the auxiliary space of an in-place two-pointer reversal?', answer: 'O(1), because only a fixed number of variables are used.' }], resources: ['neetcode', 'roadmap'] },
  { id: 'dsa-arrays', trackId: 'dsa', title: 'Arrays, hashing & prefix sums', level: 'Foundation', minutes: 24, concept: 'Arrays give constant-time indexed access but inserting in the middle shifts elements. Hash maps trade extra memory for fast key-based lookup. Prefix sums store cumulative totals so a range sum can be answered by subtracting two prefixes.', example: 'For values [2, 4, 1, 3], prefix sums can be stored as [0, 2, 6, 7, 10]. The sum from index 1 through 3 is prefix[4] − prefix[1] = 8.', interview: 'Before coding, ask whether order matters, whether duplicates exist, and whether the data is sorted. Consider a hash map for complements or frequency counts.', pitfalls: ['Forgetting that a prefix array often needs n + 1 entries.', 'Using a set when the count/frequency is needed.', 'Assuming a hash map preserves sorted order.'], checks: [{ question: 'How do you find a pair summing to target in one pass?', answer: 'For each value x, check whether target − x is already in a hash map, then record x.' }, { question: 'Why use a prefix array of length n + 1?', answer: 'It makes the sum of a half-open range [l, r) a clean subtraction: prefix[r] − prefix[l].' }], resources: ['neetcode', 'tuf'] },
  { id: 'dsa-two-pointers', trackId: 'dsa', title: 'Two pointers & sliding windows', level: 'Core', minutes: 26, concept: 'Two pointers maintain two positions that move through a sequence. Sliding windows are a specialised pattern for contiguous ranges: expand the right edge, and shrink the left edge when a condition is violated. The pattern works best when the condition changes predictably as the window moves.', example: 'For a sorted array, move the left pointer up when the sum is too small and the right pointer down when it is too large. For a longest substring with unique characters, move the left boundary until the duplicate leaves the window.', interview: 'Explain the invariant: what does the current window guarantee? Then show why each pointer moves only forward, which often proves O(n) time.', pitfalls: ['Using sliding window on a condition that is not monotonic.', 'Updating the answer before restoring the window invariant.', 'Moving both pointers without explaining why.'], checks: [{ question: 'Why can a two-pointer scan be O(n) even with a while loop inside another?', answer: 'If each pointer only moves forward, each element is entered/left at most once overall.' }, { question: 'When is a sorted array especially useful for two pointers?', answer: 'When moving one endpoint predictably increases or decreases a pair property such as sum.' }], resources: ['neetcode', 'tuf'] },
  { id: 'dsa-binary-search', trackId: 'dsa', title: 'Binary search on answers', level: 'Core', minutes: 25, concept: 'Binary search is not limited to finding a value in a sorted array. It can search a monotonic answer space: if a candidate value is feasible, all larger values (or all smaller values) may also be feasible. Define a predicate, prove monotonicity and maintain a correct boundary.', example: 'For minimum machine speed that finishes jobs within h hours, test a speed k. If k works, larger speeds also work. Binary search the smallest feasible k.', interview: 'Write down what low and high mean before writing the loop. Decide whether you need the first true, last true or exact match, and use a consistent interval convention.', pitfalls: ['Binary searching when feasibility is not monotonic.', 'Off-by-one errors from mixing inclusive and half-open intervals.', 'Using an overflow-prone midpoint expression in fixed-width languages.'], checks: [{ question: 'What property makes binary search on an answer possible?', answer: 'A monotonic feasibility predicate: once true (or false), it stays that way in one direction.' }, { question: 'What is the key invariant in first-true binary search?', answer: 'The answer remains inside the maintained search interval; the false/true boundary is never discarded.' }], resources: ['neetcode', 'tuf'] },
  { id: 'dsa-trees-graphs', trackId: 'dsa', title: 'Trees, graphs & traversal', level: 'Interview depth', minutes: 32, concept: 'A tree is a connected acyclic graph. DFS explores a branch deeply before backtracking; BFS explores by distance layers. Adjacency lists use O(V + E) memory and are usually efficient for sparse graphs. For weighted non-negative edges, Dijkstra’s algorithm is a common shortest-path choice.', example: 'In a grid, treat each cell as a vertex and valid moves as edges. BFS gives the shortest number of moves when every move has equal cost.', interview: 'Clarify whether the graph is directed, weighted and connected. State visited-state handling, traversal complexity and what the queue/stack represents.', pitfalls: ['Forgetting visited tracking in cyclic graphs.', 'Using BFS for weighted shortest paths with unequal edge costs.', 'Assuming a tree traversal always has a unique parent in a general graph.'], checks: [{ question: 'Why does BFS find shortest paths in an unweighted graph?', answer: 'It visits vertices in non-decreasing distance (number of edges) from the source.' }, { question: 'What is adjacency-list DFS complexity?', answer: 'O(V + E), since vertices and adjacency entries are processed a constant number of times.' }], resources: ['neetcode', 'tuf'] },
  // OS
  { id: 'os-process-thread', trackId: 'os', title: 'Programs, processes & threads', level: 'Foundation', minutes: 22, concept: 'A program is a passive executable file. A process is a running instance with its own virtual address space and operating-system-managed resources. Threads are execution paths within a process; they share process memory and resources but have their own stacks and CPU state. A context switch saves one execution context and restores another.', example: 'A browser may use separate processes for isolation and multiple threads inside a process for UI, networking or background work. A crash in one isolated process need not terminate every other process.', interview: 'Compare isolation, memory sharing, creation cost, communication and failure boundaries. Avoid saying threads have no private memory: each thread has its own stack and registers.', pitfalls: ['Saying a thread has its own complete address space.', 'Equating a process with a program on disk.', 'Treating context switching as free.'], checks: [{ question: 'What do threads in one process typically share?', answer: 'The address space, code, heap and process resources such as open files.' }, { question: 'What is private to an individual thread?', answer: 'Its stack, register state and program counter.' }], resources: ['ostep', 'gfg'] },
  { id: 'os-scheduling', trackId: 'os', title: 'CPU scheduling & context switches', level: 'Core', minutes: 25, concept: 'The scheduler selects a runnable task for CPU time. FCFS is simple but can cause the convoy effect. SJF minimises average waiting time when burst lengths are known; Round Robin gives each task a time slice and improves responsiveness for interactive workloads. Preemptive scheduling can interrupt a running task.', example: 'With Round Robin and a 4 ms quantum, a 10 ms task runs in slices of 4, 4 and 2 ms, alternating with other ready tasks. A very large quantum behaves more like FCFS; a tiny one increases switching overhead.', interview: 'Know turnaround time = completion − arrival, waiting time = turnaround − CPU burst, and response time = first run − arrival. Draw a Gantt chart before calculating.', pitfalls: ['Confusing waiting time with turnaround time.', 'Ignoring arrival times in scheduling calculations.', 'Assuming Round Robin always improves throughput.'], checks: [{ question: 'What is turnaround time?', answer: 'Completion time minus arrival time.' }, { question: 'What happens when the Round Robin quantum is extremely small?', answer: 'Responsiveness may improve, but context-switch overhead can become excessive.' }], resources: ['ostep', 'gfg'] },
  { id: 'os-sync', trackId: 'os', title: 'Race conditions, mutexes & semaphores', level: 'Core', minutes: 28, concept: 'A race condition occurs when correctness depends on the timing/interleaving of concurrent operations. A critical section accesses shared state. A mutex provides mutual exclusion and has ownership semantics; a semaphore is a counter used to control access to a set of resources or coordinate events. Correct synchronisation must also consider deadlock and starvation.', example: 'Two threads incrementing a shared counter can both read 7, both compute 8 and both write 8. A mutex around the read-modify-write operation makes the increment atomic with respect to other threads using the same lock.', interview: 'Explain the exact shared state, the invariant you need to preserve, and the region that must be protected. Distinguish binary semaphore from a mutex by ownership and intended use.', pitfalls: ['Assuming volatile makes compound operations thread-safe.', 'Locking different mutexes around the same shared data.', 'Forgetting to release a lock on an error path.'], checks: [{ question: 'Why is counter++ not necessarily atomic?', answer: 'It is typically a read, modify and write sequence that can interleave with another thread.' }, { question: 'What is the core purpose of a mutex?', answer: 'To ensure only one participating thread enters a protected critical section at a time.' }], resources: ['ostep', 'gfg'] },
  { id: 'os-deadlock', trackId: 'os', title: 'Deadlocks: conditions & handling', level: 'Interview depth', minutes: 24, concept: 'A deadlock is a set of tasks permanently waiting for events that only members of the set can cause. The four Coffman conditions are mutual exclusion, hold-and-wait, no preemption and circular wait. Prevention breaks at least one condition; avoidance checks whether a resource allocation keeps the system in a safe state; detection finds deadlocks after they occur.', example: 'Thread A locks X then requests Y; thread B locks Y then requests X. A consistent global lock order (always X before Y) prevents this circular-wait pattern.', interview: 'Construct a resource-allocation or wait-for graph. Explain which condition your proposed mitigation breaks and the trade-off it introduces.', pitfalls: ['Calling starvation a deadlock.', 'Confusing prevention with avoidance.', 'Suggesting timeouts without discussing partial work or retry safety.'], checks: [{ question: 'Name the four necessary Coffman conditions.', answer: 'Mutual exclusion, hold-and-wait, no preemption and circular wait.' }, { question: 'How does global lock ordering help?', answer: 'It removes circular wait by forcing every thread to acquire locks in the same order.' }], resources: ['ostep', 'gfg'] },
  { id: 'os-virtual-memory', trackId: 'os', title: 'Virtual memory, paging & TLB', level: 'Interview depth', minutes: 30, concept: 'Virtual memory gives each process a private address-space abstraction. Paging maps fixed-size virtual pages to physical frames through page tables. A TLB caches recent translations. A page fault occurs when a translation or access requires OS handling; it may be a valid page that simply is not resident, or an invalid/protected access.', example: 'A virtual address is split into a virtual page number and offset. The page table (or TLB) maps the page number to a physical frame; the offset is preserved to form the physical address.', interview: 'Walk through translation: TLB lookup, page-table walk on a miss, permission/presence check, possible fault handling, then memory access. Mention locality and why page size is a trade-off.', pitfalls: ['Saying every page fault is a program error.', 'Confusing virtual pages with physical frames.', 'Forgetting that TLB entries must respect address-space changes and permissions.'], checks: [{ question: 'Why does a TLB improve performance?', answer: 'It avoids repeating a multi-level page-table walk for translations that are cached.' }, { question: 'What is the purpose of the page offset?', answer: 'It identifies the byte within a page and remains unchanged during translation.' }], resources: ['ostep', 'gfg'] },
  // CN
  { id: 'cn-layers', trackId: 'cn', title: 'OSI, TCP/IP & encapsulation', level: 'Foundation', minutes: 22, concept: 'Layering separates networking responsibilities. The OSI model has seven conceptual layers; the Internet protocol suite is commonly described with four or five layers. As data moves down a stack, each layer adds control information (encapsulation); the receiver removes it in reverse order. Models are teaching abstractions, not literal boxes inside every device.', example: 'An HTTP request becomes application data, is carried in a TCP segment, placed inside an IP packet and transmitted in a link-layer frame.', interview: 'Map HTTP, TCP/UDP, IP and Ethernet/Wi-Fi to their roles. Explain why ports identify application endpoints while IP addresses help route between hosts.', pitfalls: ['Claiming the OSI model is the exact implementation of the Internet.', 'Mixing up IP addresses and MAC addresses.', 'Saying routers generally route by TCP port.'], checks: [{ question: 'Which layer provides end-to-end transport with ports?', answer: 'The transport layer (TCP or UDP).' }, { question: 'What is encapsulation?', answer: 'Wrapping data with protocol-specific headers (and sometimes trailers) as it moves down the stack.' }], resources: ['kurose', 'mdn-web'] },
  { id: 'cn-tcp-udp', trackId: 'cn', title: 'TCP vs UDP & reliability', level: 'Core', minutes: 26, concept: 'TCP is a connection-oriented byte stream that provides ordered, reliable delivery using sequence numbers, acknowledgements, retransmission and congestion control. UDP is a datagram transport with lower protocol overhead and no built-in delivery or ordering guarantee. Applications choose based on the semantics they need, not because one is universally faster.', example: 'A file download needs complete, ordered bytes, so TCP is a natural fit. Real-time voice/video may prefer timeliness and application-level recovery over waiting for delayed retransmissions; UDP is often used with higher-level protocols.', interview: 'Separate reliability, ordering, flow control and congestion control. Flow control protects the receiver; congestion control protects the network.', pitfalls: ['Saying UDP has no error detection at all (UDP includes a checksum, with protocol-specific details).', 'Calling TCP message-oriented; it is a byte stream.', 'Confusing flow control with congestion control.'], checks: [{ question: 'What does TCP provide that UDP does not provide by itself?', answer: 'Reliable, ordered byte-stream delivery with retransmission and congestion-control mechanisms.' }, { question: 'What does a receiver window help with?', answer: 'Flow control: it limits how much unacknowledged data the sender should have in flight for that receiver.' }], resources: ['kurose', 'mdn-web'] },
  { id: 'cn-handshake', trackId: 'cn', title: 'TCP handshake, teardown & ports', level: 'Core', minutes: 24, concept: 'TCP normally establishes a connection with SYN, SYN-ACK and ACK. This synchronises initial sequence numbers and confirms two-way reachability. Teardown uses FIN/ACK exchanges; resets can abort a connection. A port identifies a transport endpoint on a host, while a socket is commonly described by protocol plus local/remote addresses and ports.', example: 'A browser connecting to a server might use an ephemeral client port and destination port 443. The server distinguishes many concurrent connections by their endpoint tuples.', interview: 'Draw the three messages and explain what each confirms. Be precise: the handshake does not guarantee that an application is healthy or that a later request will succeed.', pitfalls: ['Calling the handshake a three-way data transfer.', 'Saying a port uniquely identifies a machine.', 'Confusing FIN (orderly close) with RST (reset).'], checks: [{ question: 'Why are there three messages in the standard TCP handshake?', answer: 'Both endpoints exchange and acknowledge initial sequence numbers, confirming each direction can communicate.' }, { question: 'What is an ephemeral port?', answer: 'A temporary client-side port selected for an outgoing connection.' }], resources: ['kurose', 'mdn-web'] },
  { id: 'cn-dns-http', trackId: 'cn', title: 'DNS, HTTP & what happens after Enter', level: 'Interview depth', minutes: 32, concept: 'A browser resolves a hostname through DNS, establishes transport connectivity, negotiates TLS for HTTPS, then sends an HTTP request. The path may include proxies, caches, load balancers and application servers. DNS answers can be cached at several layers; HTTP itself is stateless, while cookies or tokens can carry session context.', example: 'For https://example.com, the browser parses the URL, checks relevant caches, resolves an address, connects to the server (often TCP plus TLS for HTTP/1.1 or HTTP/2), sends a request and processes the response before fetching page subresources.', interview: 'Tell the story in order. Mention DNS caching, TLS certificate validation, the Host header/SNI where relevant, status codes, caches and the possibility of multiple backend services.', pitfalls: ['Claiming DNS always means one query to a root server.', 'Saying HTTPS is a separate application protocol from HTTP rather than HTTP over a secure transport.', 'Ignoring caching and connection reuse.'], checks: [{ question: 'What does DNS primarily resolve in a typical web request?', answer: 'A hostname to records such as IP addresses, subject to record type and resolver behavior.' }, { question: 'Why can HTTP be called stateless?', answer: 'The protocol does not inherently remember application state between independent requests; cookies or tokens add session context.' }], resources: ['mdn-web', 'kurose'] },
  { id: 'cn-tls', trackId: 'cn', title: 'TLS, certificates & HTTPS', level: 'Interview depth', minutes: 26, concept: 'TLS protects data in transit by providing confidentiality and integrity, and authenticates the server using certificates in common HTTPS deployments. A certificate binds an identity to a public key and is validated through a trusted chain, hostname checks and validity constraints. Modern TLS uses asymmetric cryptography during authentication/key establishment and symmetric keys for bulk traffic.', example: 'The browser verifies that the certificate chain is trusted and the certificate matches the requested hostname. The peers derive session keys, then protect application records with authenticated encryption.', interview: 'Explain trust-chain validation, hostname validation and why symmetric encryption is used for application data. Do not describe the TLS handshake as a single fixed sequence across all versions.', pitfalls: ['Saying the certificate encrypts all page traffic.', 'Assuming a padlock proves a website is honest or non-malicious.', 'Confusing encryption with authentication.'], checks: [{ question: 'What does a server certificate help the client verify?', answer: 'That the public key is associated with the intended server identity under a trusted certificate chain.' }, { question: 'Why use symmetric encryption after the handshake?', answer: 'It is efficient for protecting large amounts of application data.' }], resources: ['mdn-web', 'kurose'] },
  // DBMS
  { id: 'dbms-model', trackId: 'dbms', title: 'Relational model, keys & constraints', level: 'Foundation', minutes: 24, concept: 'A relational database organises data into relations (tables) with rows and columns. A primary key uniquely identifies a row and cannot be NULL. A foreign key enforces a relationship to a referenced candidate/unique key. Constraints move integrity rules close to the data so every client observes them.', example: 'Students(student_id PRIMARY KEY, name) and Enrolments(student_id FOREIGN KEY, course_id) model a many-to-many relationship between students and courses.', interview: 'Distinguish superkey, candidate key, primary key and foreign key. Explain how NULL interacts with uniqueness and referential integrity in the database you use.', pitfalls: ['Calling a foreign key automatically unique.', 'Assuming a primary key must be a single column.', 'Treating NULL as equal to zero or an empty string.'], checks: [{ question: 'Can a primary key contain multiple columns?', answer: 'Yes. A composite primary key uniquely identifies a row using more than one column.' }, { question: 'What does a foreign key protect?', answer: 'Referential integrity between referencing rows and referenced keys.' }], resources: ['postgres', 'sqlbolt', 'gfg'] },
  { id: 'dbms-normalisation', trackId: 'dbms', title: 'Functional dependencies & normalisation', level: 'Core', minutes: 28, concept: 'Normalisation structures relations to reduce undesirable redundancy and update anomalies. A functional dependency X → Y means X determines Y. 1NF requires atomic attribute values under the chosen model; 2NF removes partial dependencies of non-prime attributes on a candidate key; 3NF addresses transitive dependencies with a formal condition; BCNF requires every determinant to be a superkey.', example: 'If a table repeats department_name for every employee, separating Department(department_id, department_name) can prevent a department rename from requiring many row updates.', interview: 'Start from the key and dependencies, not memorised labels. State which anomaly exists, which dependency causes it and what decomposition fixes it.', pitfalls: ['Saying 2NF is simply “no duplicate data”.', 'Assuming every decomposition is lossless or dependency-preserving.', 'Normalising without considering read patterns and deliberate denormalisation.'], checks: [{ question: 'What is an update anomaly?', answer: 'A data change must be repeated across multiple rows, creating inconsistency risk.' }, { question: 'What is the BCNF rule?', answer: 'For every non-trivial functional dependency X → Y, X must be a superkey.' }], resources: ['postgres', 'gfg'] },
  { id: 'dbms-sql-joins', trackId: 'dbms', title: 'SQL joins, grouping & NULL', level: 'Core', minutes: 30, concept: 'JOIN combines rows based on a relationship. INNER JOIN keeps matching pairs; LEFT JOIN keeps all left rows and fills missing right-side columns with NULL. GROUP BY forms groups for aggregates. SQL uses three-valued logic: a comparison with NULL is generally UNKNOWN, so use IS NULL rather than = NULL.', example: 'To retain customers with no orders, LEFT JOIN customers to orders and filter for orders.order_id IS NULL. Put right-table filters in the ON clause when unmatched left rows must remain.', interview: 'Predict row cardinality before writing the query. Watch one-to-many joins that multiply rows, and distinguish WHERE (before grouping) from HAVING (after grouping).', pitfalls: ['Filtering the nullable side in WHERE and accidentally turning a LEFT JOIN into an inner join.', 'Using COUNT(*) when you intended to count non-NULL values in a column.', 'Forgetting duplicate multiplication from joins.'], checks: [{ question: 'What is the difference between WHERE and HAVING?', answer: 'WHERE filters input rows before grouping; HAVING filters groups after aggregation.' }, { question: 'How do you test for a missing value?', answer: 'Use IS NULL or IS NOT NULL, not = NULL.' }], resources: ['sqlbolt', 'postgres'] },
  { id: 'dbms-acid', trackId: 'dbms', title: 'Transactions & ACID', level: 'Interview depth', minutes: 28, concept: 'A transaction groups operations into a logical unit. Atomicity means all-or-nothing; consistency means constraints/invariants are preserved; isolation controls interference between concurrent transactions; durability means committed work survives failures under the database’s guarantees. The exact isolation behavior is defined by the database engine and isolation level.', example: 'A bank transfer debits one account and credits another. Both updates must commit together; if the second fails, the first must not remain committed by itself.', interview: 'Explain what can go wrong without a transaction, then explain the selected isolation level and the anomaly it prevents. Distinguish ACID consistency from application business logic.', pitfalls: ['Saying isolation always means transactions run one at a time.', 'Treating ACID consistency as “the database is always correct”.', 'Assuming every database implements all isolation levels identically.'], checks: [{ question: 'Which ACID property protects committed data after a crash?', answer: 'Durability.' }, { question: 'What is a dirty read?', answer: 'Reading data written by another transaction that has not yet committed.' }], resources: ['postgres', 'gfg'] },
  { id: 'dbms-index', trackId: 'dbms', title: 'Indexes, B-trees & query plans', level: 'Interview depth', minutes: 30, concept: 'An index is an auxiliary data structure that helps find rows without scanning the whole table. B-tree indexes support ordered lookups and ranges. Indexes speed some reads but consume space and add work to inserts, updates and deletes. The query planner estimates costs and chooses a plan based on statistics and available access paths.', example: 'An index on (last_name, first_name) may help queries filtering by last_name or both columns, but usually cannot provide the same efficient lookup for first_name alone because of the leftmost-prefix ordering.', interview: 'Describe selectivity, composite-index column order, covering/index-only access and write overhead. Ask for EXPLAIN/EXPLAIN ANALYZE rather than guessing from query text.', pitfalls: ['Adding an index to every column.', 'Assuming an index is always used.', 'Ignoring stale statistics and actual row counts.'], checks: [{ question: 'Why can too many indexes hurt?', answer: 'They consume storage and add maintenance work to data writes and vacuum/maintenance operations.' }, { question: 'What does EXPLAIN show?', answer: 'The database’s planned execution strategy; EXPLAIN ANALYZE also executes and reports observed runtime details.' }], resources: ['postgres', 'gfg'] },
  // OOP
  { id: 'oops-pillars', trackId: 'oops', title: 'The four pillars, with useful boundaries', level: 'Foundation', minutes: 24, concept: 'Encapsulation groups state and behaviour behind a controlled interface. Abstraction exposes essential operations while hiding implementation detail. Inheritance derives a type from another type. Polymorphism lets code use a common interface while behaviour varies by concrete implementation. These are design tools, not goals to maximise.', example: 'A PaymentMethod interface can define pay(amount). CardPayment and UpiPayment implement it differently. The checkout flow depends on the interface, not on the concrete payment class.', interview: 'Give a small code-level example and explain the benefit. For polymorphism, distinguish compile-time overloading from runtime overriding/dispatch.', pitfalls: ['Using getters and setters everywhere and calling it meaningful encapsulation.', 'Confusing abstraction with inheritance.', 'Making inheritance deep just to reuse implementation.'], checks: [{ question: 'Which pillar allows one interface to have different implementations?', answer: 'Polymorphism.' }, { question: 'What is the practical purpose of encapsulation?', answer: 'Protect invariants by controlling how an object’s internal state can be read or changed.' }], resources: ['oracle-oop', 'dev-java'] },
  { id: 'oops-overload-override', trackId: 'oops', title: 'Overloading, overriding & interfaces', level: 'Core', minutes: 22, concept: 'Overloading uses the same method name with different parameter lists and is generally resolved at compile time. Overriding provides a subtype-specific implementation of an inherited method and participates in dynamic dispatch. An interface describes a contract; an abstract class can also hold shared state and implementation, depending on the language.', example: 'print(int) and print(String) are overloads. If Shape has an area() method and Circle overrides it, a Shape reference holding a Circle calls Circle.area() through runtime dispatch.', interview: 'Explain resolution using reference type, parameter signature and runtime object type. Mention language-specific rules for static methods, visibility, covariant returns and default methods when relevant.', pitfalls: ['Claiming return type alone distinguishes overloads in Java.', 'Claiming static methods are overridden with runtime dispatch.', 'Treating interface and abstract class as interchangeable in every language.'], checks: [{ question: 'What decides an overridden instance method implementation at runtime?', answer: 'The actual object type (subject to the language’s dispatch rules).' }, { question: 'Can methods be overloaded only by changing return type in Java?', answer: 'No. The parameter list must differ.' }], resources: ['oracle-oop', 'dev-java'] },
  { id: 'oops-composition', trackId: 'oops', title: 'Composition over inheritance', level: 'Core', minutes: 22, concept: 'Inheritance models an “is-a” relationship and couples a subtype to its base class contract. Composition builds behaviour by delegating to collaborating objects. Prefer composition when a component can vary independently, when the relationship is “has-a”, or when inheritance would expose methods that do not make sense for every subtype.', example: 'A Car has an Engine; it should usually hold an Engine object rather than inherit from Engine. A notification service can hold a Sender strategy so EmailSender and SmsSender can be swapped without changing business logic.', interview: 'Discuss substitutability, coupling, testability and where the variability lives. Inheritance is appropriate when the subtype genuinely honours the base type’s behavioural contract.', pitfalls: ['Using inheritance for code reuse alone.', 'Building a highly fragmented object graph with no clear ownership.', 'Ignoring lifecycle and dependency management.'], checks: [{ question: 'What relationship does composition usually model?', answer: 'A has-a/uses-a relationship between collaborating objects.' }, { question: 'When is inheritance appropriate?', answer: 'When the subtype is behaviourally substitutable for the base type and the hierarchy represents a real type relationship.' }], resources: ['oracle-oop', 'dev-java'] },
  { id: 'oops-solid', trackId: 'oops', title: 'SOLID, explained through change', level: 'Interview depth', minutes: 30, concept: 'SOLID is a set of design principles: Single Responsibility, Open/Closed, Liskov Substitution, Interface Segregation and Dependency Inversion. Their common theme is containing the impact of change. They are heuristics for managing coupling, not rigid laws requiring one class per method.', example: 'If invoice calculation, persistence and email are all in one class, changes to storage or notification force edits to the same unit. Separate responsibilities and depend on abstractions where the variation justifies it.', interview: 'For each principle, show a concrete “before and after”. Explain what becomes easier to change or test, and acknowledge the cost of extra abstractions.', pitfalls: ['Treating SRP as “one method per class”.', 'Applying interfaces where there is only one stable implementation and no meaningful boundary.', 'Confusing dependency inversion with dependency injection (one can help implement the other).'], checks: [{ question: 'What does Liskov Substitution protect?', answer: 'Code using a base type should continue to work when given a valid subtype without surprising contract violations.' }, { question: 'What is the difference between DIP and DI?', answer: 'DIP is a design principle about depending on abstractions; DI is a technique for supplying dependencies from outside.' }], resources: ['oracle-oop', 'roadmap'] },
  { id: 'oops-patterns', trackId: 'oops', title: 'Patterns worth recognising', level: 'Interview depth', minutes: 28, concept: 'Design patterns are reusable structures for recurring design pressures. Strategy encapsulates interchangeable algorithms; Factory centralises object creation; Observer notifies subscribers when a subject changes; Decorator adds behaviour around an object without changing its type. Use patterns to clarify a real pressure, not to decorate simple code.', example: 'A payment system can choose a Strategy based on payment type. A notification publisher can use Observer to notify email, SMS and in-app subscribers when an order ships.', interview: 'Name the problem first, then show the roles and trade-offs. Be ready to explain when a simpler conditional or function would be clearer.', pitfalls: ['Forcing a named pattern onto a tiny problem.', 'Confusing Factory Method with Abstract Factory.', 'Ignoring lifecycle, ordering and error handling in Observer systems.'], checks: [{ question: 'Which pattern encapsulates interchangeable algorithms?', answer: 'Strategy.' }, { question: 'Which pattern lets subscribers react to a subject’s state change?', answer: 'Observer / publish-subscribe.' }], resources: ['roadmap', 'oracle-oop'] },
  // System design
  { id: 'sd-process', trackId: 'system-design', title: 'A repeatable design interview approach', level: 'Foundation', minutes: 22, concept: 'A good design interview is a conversation about constraints and trade-offs. Start by clarifying functional requirements and explicit non-functional goals. Estimate traffic and data volume, define APIs and data models, sketch the high-level architecture, then deep-dive into the hardest bottleneck and failure mode.', example: 'For a URL shortener, clarify expiry, custom aliases, analytics and read/write ratio. Estimate key creation and redirect volume before choosing storage and cache strategies.', interview: 'Keep the interviewer involved. State assumptions, ask which requirement matters most, and revisit design choices when scale or reliability constraints change.', pitfalls: ['Jumping into microservices before clarifying the product.', 'Listing technologies without explaining why.', 'Ignoring failure modes and operational cost.'], checks: [{ question: 'What should come before drawing boxes?', answer: 'Clarify functional requirements, quality goals, constraints and assumptions.' }, { question: 'Why estimate scale?', answer: 'Traffic and data estimates help justify choices for partitioning, caching, storage and capacity.' }], resources: ['system-primer', 'neetcode-sd'] },
  { id: 'sd-scale', trackId: 'system-design', title: 'Capacity, latency & availability', level: 'Core', minutes: 28, concept: 'Throughput measures work completed per unit time; latency measures time for an operation. Availability describes whether a service is usable when requested. Capacity estimates translate product assumptions into requests/second, storage growth, bandwidth and concurrency. A design should identify the metric it is optimising because improving one can worsen another.', example: 'If 2 million users each create 3 events/day, that is 6 million writes/day, about 69 writes/second on average. Peak traffic may be several times higher, so average load alone is not a safe capacity target.', interview: 'Show units in every estimate. Separate average from peak and state assumptions such as payload size, retention and replication overhead.', pitfalls: ['Mixing bits and bytes.', 'Ignoring peak-to-average ratio.', 'Treating a high availability target as a guarantee without redundancy and failure handling.'], checks: [{ question: 'What is throughput?', answer: 'The rate at which a system completes operations or processes data.' }, { question: 'Why does an average requests-per-second estimate not fully determine capacity?', answer: 'Traffic is bursty; peak load, retries, fan-out and headroom matter.' }], resources: ['system-primer', 'neetcode-sd'] },
  { id: 'sd-cache', trackId: 'system-design', title: 'Caching & content delivery', level: 'Core', minutes: 25, concept: 'A cache stores copies of data closer to where they are used to reduce latency and origin load. Cache-aside is common: the application checks the cache, reads from the database on a miss, then populates the cache. Invalidation, staleness, stampedes and cache-key design are the hard parts.', example: 'A product page can cache mostly static product details for a short TTL. Inventory may need stricter freshness or a separate reservation path to avoid selling unavailable stock.', interview: 'Identify what can be stale, for how long, and who invalidates it. Discuss TTL, explicit invalidation, hot keys, stampede protection and cache failure behaviour.', pitfalls: ['Caching mutable state with no freshness policy.', 'Assuming a cache is always faster under every workload.', 'Failing to plan for a cold cache or cache outage.'], checks: [{ question: 'What is cache-aside?', answer: 'The application checks the cache, fetches from the backing store on a miss and fills the cache.' }, { question: 'What is a cache stampede?', answer: 'Many requests simultaneously miss/expire a hot key and overload the backing store.' }], resources: ['system-primer', 'roadmap'] },
  { id: 'sd-storage', trackId: 'system-design', title: 'SQL, NoSQL & data partitioning', level: 'Interview depth', minutes: 30, concept: 'Relational databases fit structured data, transactions and expressive joins. Key-value, document, wide-column and graph stores optimise different access patterns. Partitioning spreads data across nodes; sharding adds routing and operational complexity. Choose a data model from query patterns and consistency needs, not from fashion.', example: 'A chat application might store message history partitioned by conversation ID and time. This supports loading a conversation’s recent messages while requiring attention to hot conversations and retention.', interview: 'Write the main queries before choosing a store. Discuss partition key, hot partitions, secondary indexes, replication, consistency and migration strategy.', pitfalls: ['Calling NoSQL “schema-less” or transaction-free.', 'Choosing a shard key with skewed access.', 'Ignoring cross-shard queries and rebalancing.'], checks: [{ question: 'What is a shard key?', answer: 'The field or derived value used to assign records to partitions/nodes.' }, { question: 'What is a hot partition?', answer: 'A partition receiving a disproportionate share of traffic or data, becoming a bottleneck.' }], resources: ['system-primer', 'postgres'] },
  { id: 'sd-reliability', trackId: 'system-design', title: 'Queues, retries & failure isolation', level: 'Interview depth', minutes: 30, concept: 'A queue decouples producers from consumers and absorbs bursts. Retries can recover transient failures but must be bounded and usually use backoff with jitter. At-least-once delivery means consumers may see duplicates, so idempotency matters. Circuit breakers and bulkheads help stop a failing dependency from spreading failure through the whole system.', example: 'An order service writes an event to a durable queue. A worker processes it and records an idempotency key; if the message is redelivered, the repeated operation does not create a second shipment.', interview: 'Explain delivery semantics, dead-letter handling, poison messages, retry budgets and what happens when the consumer is slower than the producer.', pitfalls: ['Retrying forever with no backoff.', 'Assuming exactly-once processing across independent systems is easy.', 'Using a queue without defining ordering requirements.'], checks: [{ question: 'Why should message consumers be idempotent?', answer: 'Messages may be delivered more than once; repeating the operation should not create duplicate side effects.' }, { question: 'What does a dead-letter queue help with?', answer: 'It isolates messages that repeatedly fail so they can be inspected or replayed without blocking normal work.' }], resources: ['system-primer', 'roadmap'] },
  // Aptitude
  { id: 'apt-work', trackId: 'aptitude', title: 'Time, work & combined rates', level: 'Foundation', minutes: 20, concept: 'Convert work into rates. If A completes a job in x days, A’s one-day rate is 1/x. Combined rates add when workers act independently on the same job. Keep the unit consistent and invert the combined rate only at the end to get total time.', example: 'A completes 2/3 of a task in 5 days, so A’s full-task rate is (2/3)/5 = 2/15 per day. B completes 4/5 in 8 days, so B’s rate is 1/10. Together they work at 7/30 per day and need 30/7 days.', interview: 'Write rates as fractions of the whole task per unit time. Check that the combined rate is greater than either individual rate and that total time is therefore smaller.', pitfalls: ['Adding completion times instead of rates.', 'Mixing “fraction completed” with “time taken for whole work”.', 'Forgetting the unit in the final answer.'], checks: [{ question: 'If A takes 6 days for a job, what is A’s rate?', answer: '1/6 of the job per day.' }, { question: 'Why do we add rates rather than days?', answer: 'Independent workers contribute work simultaneously; their per-unit-time contributions add.' }], resources: ['gfg'] },
  { id: 'apt-percentages', trackId: 'aptitude', title: 'Percentages, ratios & averages', level: 'Foundation', minutes: 22, concept: 'Percent means per hundred. For successive percentage changes, multiply the change factors rather than adding percentages. Ratios compare quantities in a common scale. Averages are totals divided by count, so weighted averages must account for group sizes.', example: 'A price rises 20% then falls 20%: 1.2 × 0.8 = 0.96, so the final price is 4% below the original, not unchanged.', interview: 'Translate each percentage into a multiplier. For ratio questions, assign a common variable to each part before substituting totals.', pitfalls: ['Adding sequential percentage changes.', 'Taking an unweighted average of group averages.', 'Switching the base quantity midway through the question.'], checks: [{ question: 'What is the net effect of +10% followed by −10%?', answer: '0.9 × 1.1 = 0.99, a net decrease of 1%.' }, { question: 'When is a weighted average required?', answer: 'When groups have different sizes or contribute different amounts.' }], resources: ['gfg'] },
  { id: 'apt-probability', trackId: 'aptitude', title: 'Probability & counting basics', level: 'Core', minutes: 24, concept: 'Probability is favourable outcomes divided by equally likely outcomes. The complement rule is often easier: P(at least one) = 1 − P(none). Permutations count ordered arrangements; combinations count selections where order does not matter. Always define the sample space before calculating.', example: 'For two independent fair coin tosses, the probability of at least one head is 1 − P(two tails) = 1 − 1/4 = 3/4.', interview: 'Check whether events are independent, mutually exclusive or conditional. Use a small sample space for simple cases to validate the formula.', pitfalls: ['Assuming events are independent without justification.', 'Using permutations when order does not matter.', 'Double-counting overlapping cases.'], checks: [{ question: 'When is the complement rule helpful?', answer: 'When counting “at least one” is harder than counting “none”.' }, { question: 'What is the difference between permutation and combination?', answer: 'Permutation is order-sensitive; combination is not.' }], resources: ['gfg'] },
  { id: 'apt-reasoning', trackId: 'aptitude', title: 'Reasoning under a timer', level: 'Interview depth', minutes: 18, concept: 'Timed reasoning is partly a selection problem. Identify the question type quickly, write down constraints and eliminate impossible options. Skip a question when the expected time cost is high, then return after collecting easier marks. Accuracy usually matters more than a small speed gain that creates careless errors.', example: 'For seating arrangements, anchor one fixed person to remove rotationally equivalent arrangements, then add constraints one at a time instead of testing every permutation.', interview: 'Practise in short timed sets and review why each wrong answer happened: concept gap, misread condition, arithmetic or time pressure.', pitfalls: ['Spending too long on one puzzle.', 'Changing a correct answer without a reason.', 'Practising only untimed questions.'], checks: [{ question: 'What is a useful first step for a constraint puzzle?', answer: 'Translate each sentence into a constraint and choose a fixed anchor if symmetry allows.' }, { question: 'What should an error log capture?', answer: 'Question type, cause of error, correct reasoning and the cue to recognise it next time.' }], resources: ['gfg'] },

  // Additional depth: coding patterns and commonly skipped core-CS details
  { id: 'dsa-stacks-queues', trackId: 'dsa', title: 'Stacks, queues & monotonic structures', level: 'Core', minutes: 24, concept: 'A stack is last-in, first-out; a queue is first-in, first-out. They are useful when the order of pending work matters: DFS uses a stack, BFS uses a queue, and parsers use stacks to match nested structure. A monotonic stack maintains increasing or decreasing values so the next greater/smaller element can be found in linear time.', example: 'For each bar in a histogram, a monotonic increasing stack keeps indices whose heights have not yet found a smaller bar. When a shorter bar arrives, pop taller bars and calculate the widest rectangle for each popped height.', interview: 'Explain what each stack entry represents and why each item is pushed and popped at most once. That amortised argument is often the key to proving O(n).', pitfalls: ['Storing values when indices are needed to calculate distances.', 'Using a stack when a queue is required for level-order traversal.', 'Forgetting to flush remaining stack entries after the scan.'], checks: [{ question: 'Why can a monotonic stack solve next-greater-element in O(n)?', answer: 'Each index is pushed once and popped at most once, so total stack operations are linear.' }, { question: 'Which structure is natural for BFS?', answer: 'A FIFO queue, because it visits vertices in increasing distance layers.' }], resources: ['neetcode', 'tuf'] },
  { id: 'dsa-heaps-intervals', trackId: 'dsa', title: 'Heaps, top-K & interval problems', level: 'Interview depth', minutes: 28, concept: 'A binary heap is a complete binary tree that exposes the smallest or largest element efficiently. A min-heap supports repeated extract-min in O(log n), making it useful for top-K selection, merging sorted streams and scheduling. Interval problems usually become simpler after sorting by start or end and defining whether touching boundaries overlap.', example: 'To find the k largest values, maintain a min-heap of size k. For each value, insert while the heap is small; otherwise replace the minimum only when the new value is larger. The heap contains the best k seen so far.', interview: 'Compare sorting all n values (O(n log n)) with a size-k heap (O(n log k)). State the heap invariant and define inclusive versus exclusive interval boundaries.', pitfalls: ['Building a heap of all values when k is much smaller than n.', 'Sorting intervals by the wrong endpoint for the chosen greedy rule.', 'Treating [1, 3] and [3, 5] as overlapping without checking the problem convention.'], checks: [{ question: 'What is the time complexity of inserting into a binary heap?', answer: 'O(log n), because an element may move along the heap height.' }, { question: 'Why can a size-k min-heap find the k largest values?', answer: 'Its root is the smallest retained candidate, so it is the easiest retained value to replace.' }], resources: ['neetcode', 'tuf'] },
  { id: 'dsa-dp', trackId: 'dsa', title: 'Dynamic programming: states before code', level: 'Interview depth', minutes: 34, concept: 'Dynamic programming applies when a problem has overlapping subproblems and an optimal substructure. Define a state that captures exactly the information needed, write the recurrence, identify base cases, then choose memoisation or tabulation. Space optimisation is valid only when discarded states can no longer affect future transitions.', example: 'For climbing stairs, dp[i] can mean the number of ways to reach step i. The recurrence is dp[i] = dp[i−1] + dp[i−2], with base values chosen from the problem definition. The recurrence can be reduced to two rolling variables.', interview: 'Say what dp[i] means in one sentence before writing a recurrence. Derive transitions from the final choice, test a tiny input manually, then analyse state count × transition cost.', pitfalls: ['Writing a recurrence before defining the state.', 'Using an incorrect base case for n = 0 or n = 1.', 'Optimising memory before proving which previous states are needed.'], checks: [{ question: 'What are the usual ingredients of a DP solution?', answer: 'A state definition, transition/recurrence, base cases, evaluation order and complexity.' }, { question: 'When is memoisation useful?', answer: 'When a recursive recurrence has overlapping states and caching avoids recomputing them.' }], resources: ['neetcode', 'tuf'] },
  { id: 'os-syscalls', trackId: 'os', title: 'User mode, kernel mode & system calls', level: 'Core', minutes: 20, concept: 'Modern CPUs distinguish privilege levels so ordinary applications cannot directly perform privileged operations. A system call is a controlled entry into the kernel to request services such as file I/O, process creation or memory mapping. The transition saves enough execution state, validates arguments and returns a result or error.', example: 'A program calling read() asks the kernel to read from a file descriptor. The call may block while data arrives; the kernel checks permissions and copies or maps data according to the operating system and API.', interview: 'Distinguish a library function from a system call: a library wrapper may do user-space work before entering the kernel. Explain the privilege transition and why it is not simply an ordinary function call.', pitfalls: ['Assuming every library call is a system call.', 'Saying a mode switch always implies a process context switch.', 'Ignoring permission checks and error returns.'], checks: [{ question: 'Why do applications use system calls?', answer: 'To request privileged kernel services through a controlled, validated interface.' }, { question: 'Does every system call switch to another process?', answer: 'No. A mode transition can occur while the same process remains the running task.' }], resources: ['ostep'] },
  { id: 'os-filesystems', trackId: 'os', title: 'Filesystems, buffering & I/O', level: 'Interview depth', minutes: 26, concept: 'A filesystem maps names and directories to metadata and storage blocks. File descriptors are process-local handles to open kernel-managed objects. Buffering and caching reduce expensive device operations, while durability depends on the filesystem, device and application write protocol. Sequential and random I/O can have very different costs.', example: 'A write() returning successfully may mean data reached a kernel buffer, not necessarily stable storage. Applications that need crash durability may need an explicit synchronisation operation and must understand ordering guarantees.', interview: 'Explain the path from file name lookup to an open descriptor, and distinguish visibility, completion and durability. Mention metadata, permissions and buffering where relevant.', pitfalls: ['Treating close() as a universal durability guarantee.', 'Confusing a file descriptor with a pathname.', 'Assuming all storage devices have identical random-access costs.'], checks: [{ question: 'What does a file descriptor represent?', answer: 'A process-local integer handle referring to an open kernel-managed I/O object.' }, { question: 'Why is buffering used?', answer: 'To batch operations and reduce the overhead of interacting with slower I/O devices.' }], resources: ['ostep'] },
  { id: 'cn-addressing', trackId: 'cn', title: 'MAC, IP, ARP, routing & NAT', level: 'Core', minutes: 28, concept: 'MAC addresses identify interfaces on a local link; IP addresses support logical addressing across networks. ARP (for IPv4) discovers a local next-hop MAC address for an IP destination. Routers forward packets between networks using routing tables. NAT rewrites address/port information at a network boundary, often allowing many private hosts to share a public address.', example: 'When a host sends to an off-subnet destination, it usually sends the Ethernet frame to its default gateway’s MAC address while the IP packet retains the remote destination IP. The router then forwards the packet toward the next hop.', interview: 'Trace both layers separately: identify the destination IP and the link-layer next hop. Clarify that ARP resolves a local-link neighbour, not an arbitrary remote host.', pitfalls: ['Thinking MAC addresses are routed end-to-end across the Internet.', 'Confusing a default gateway with a DNS server.', 'Treating NAT as a replacement for a firewall or a routing protocol.'], checks: [{ question: 'For a remote IP destination, whose MAC address is normally used on the first Ethernet hop?', answer: 'The default gateway interface’s MAC address.' }, { question: 'What does ARP resolve?', answer: 'An IPv4 address to a link-layer address on the local network segment.' }], resources: ['kurose', 'mdn-web'] },
  { id: 'cn-flow-control', trackId: 'cn', title: 'Flow control, congestion control & retransmission', level: 'Interview depth', minutes: 30, concept: 'Flow control protects a receiver from being overwhelmed; TCP advertises a receive window based on available receive-buffer capacity. Congestion control protects the network from excessive offered load and adjusts the sender’s rate using signals such as loss and delay. Retransmission and acknowledgements help recover from loss, but they do not make delay or congestion disappear.', example: 'A TCP sender can be constrained by both the receiver window and the congestion window. The effective amount of outstanding data is bounded by the smaller of the two, so a fast network can still be limited by a slow receiver.', interview: 'State which resource each mechanism protects. Discuss sequence numbers, acknowledgements, retransmission timeout and why packet loss can trigger congestion responses.', pitfalls: ['Using flow control and congestion control interchangeably.', 'Assuming a retransmission always means congestion.', 'Confusing bandwidth with throughput or latency.'], checks: [{ question: 'What does TCP flow control protect?', answer: 'The receiver’s ability to accept and buffer incoming data.' }, { question: 'What does congestion control protect?', answer: 'The network path from excessive traffic and congestion collapse.' }], resources: ['kurose'] },
  { id: 'cn-http-semantics', trackId: 'cn', title: 'HTTP methods, status codes & state', level: 'Core', minutes: 24, concept: 'HTTP is an application-layer request/response protocol. Methods communicate intended semantics: GET retrieves a representation, POST submits data for processing, PUT replaces a target representation and DELETE requests removal. Status codes describe the outcome class. HTTP is stateless by design; cookies, tokens or server-side sessions can associate requests with application state.', example: 'A browser may send GET /products?page=2 and receive 200 with a representation. A successful resource creation may return 201 and a Location header pointing to the new resource.', interview: 'Distinguish safe methods from idempotent methods. Discuss status families, cache validators, cookies and why HTTPS is required for confidentiality and integrity in transit.', pitfalls: ['Calling POST idempotent by default.', 'Returning 200 for every outcome without meaningful semantics.', 'Assuming cookies are automatically secure without flags and transport protection.'], checks: [{ question: 'What does idempotent mean for an HTTP method?', answer: 'Repeating the same request has the same intended server effect as making it once, even if responses differ.' }, { question: 'What is the purpose of a 201 status?', answer: 'It indicates a resource was created successfully.' }], resources: ['mdn-web', 'kurose'] },
  { id: 'dbms-isolation', trackId: 'dbms', title: 'Isolation levels & concurrency anomalies', level: 'Interview depth', minutes: 30, concept: 'Concurrent transactions can observe or overwrite one another in ways that violate application expectations. Common anomalies include dirty reads, non-repeatable reads, phantom reads and lost updates. Isolation levels constrain which anomalies are allowed, but the exact implementation and guarantees depend on the database engine.', example: 'Two transactions read the same account balance and both subtract a purchase. If updates overwrite one another without suitable locking or concurrency control, one withdrawal may disappear. A conditional update or stronger transaction strategy can prevent the lost update.', interview: 'Describe the schedule, not just the level name. Ask which database is used, because READ COMMITTED and REPEATABLE READ implementations differ between systems.', pitfalls: ['Assuming isolation-level names have identical implementation details everywhere.', 'Thinking ACID isolation always means serial execution.', 'Using a transaction without considering retry behaviour after serialization failure.'], checks: [{ question: 'What is a dirty read?', answer: 'Reading data written by another transaction that has not committed.' }, { question: 'Why might a serializable transaction need retry logic?', answer: 'The database may abort a transaction when concurrent execution cannot be safely serialised.' }], resources: ['postgres'] },
  { id: 'dbms-window', trackId: 'dbms', title: 'Window functions, CTEs & analytical SQL', level: 'Interview depth', minutes: 28, concept: 'A window function calculates across related rows without collapsing them into one grouped row. PARTITION BY defines the group of rows and ORDER BY defines their sequence. CTEs give a query a named logical step and can improve readability; they are not automatically faster than an equivalent subquery.', example: 'ROW_NUMBER() OVER (PARTITION BY department ORDER BY salary DESC) can rank employees within each department. Filtering rank = 1 in an outer query returns the highest-paid row per department, with tie-handling chosen deliberately.', interview: 'Explain the difference between GROUP BY and window functions, then call out tie semantics: ROW_NUMBER, RANK and DENSE_RANK do not behave identically.', pitfalls: ['Filtering a window alias in WHERE at the same query level.', 'Forgetting deterministic tie-breaking when exactly one row is required.', 'Assuming a CTE is always materialised or always inlined.'], checks: [{ question: 'What is the key difference between GROUP BY and a window function?', answer: 'GROUP BY collapses rows into groups; window functions preserve individual rows while computing across a related set.' }, { question: 'When would DENSE_RANK differ from ROW_NUMBER?', answer: 'DENSE_RANK gives equal values the same rank without gaps; ROW_NUMBER always assigns a distinct sequence.' }], resources: ['postgres', 'sqlbolt'] },
  { id: 'oop-contracts', trackId: 'oops', title: 'Interfaces, abstract classes & contracts', level: 'Core', minutes: 22, concept: 'An interface expresses a capability or contract that different implementations can satisfy. An abstract class can combine a shared contract with common state or partial implementation. The choice is language-dependent, but the design question is stable: which behaviour must callers rely on, and which implementation details should remain replaceable?', example: 'A NotificationSender interface can be implemented by EmailSender and SmsSender. A service depends on the interface, so tests can inject a fake sender and production can choose an implementation without changing business logic.', interview: 'Talk about substitutability, dependency direction and test seams. Avoid claiming interfaces are always better: shared state or tightly related implementation can justify an abstract base class.', pitfalls: ['Putting every method into one “god” interface.', 'Depending on a concrete implementation when the abstraction is the true requirement.', 'Using inheritance solely to reuse code when the subtype is not behaviourally substitutable.'], checks: [{ question: 'Why depend on an interface in a service?', answer: 'It reduces coupling to one implementation and makes alternative implementations and test doubles easier to substitute.' }, { question: 'What is a common reason for an abstract class?', answer: 'Related subclasses need a shared partial implementation or common protected state alongside an abstract contract.' }], resources: ['dev-java', 'oracle-oop'] },
  { id: 'sd-consistency', trackId: 'system-design', title: 'Consistency, replication & CAP trade-offs', level: 'Interview depth', minutes: 32, concept: 'Replication keeps copies of data on multiple nodes to improve availability, locality or read capacity. Replicas can lag, so a read may be stale. Strong consistency gives clients a stronger view of completed writes but can cost latency or availability during failures. CAP is about the trade-off between consistency and availability when a network partition occurs; it is not a blanket rule that every system chooses only two of three at all times.', example: 'A user updating a profile may expect read-your-writes behaviour immediately. The service can route that user to the leader or use a session consistency token while allowing other readers to use lagging replicas.', interview: 'State the failure model and consistency guarantee before saying “CP” or “AP”. Explain leader/follower roles, replica lag and the application-level consequence of stale reads.', pitfalls: ['Treating CAP as a simple menu unrelated to network partitions.', 'Equating replication with backup.', 'Ignoring read-after-write requirements and conflict resolution.'], checks: [{ question: 'What is replica lag?', answer: 'The delay between a write being accepted and that write becoming visible on a replica.' }, { question: 'When does the classic CAP trade-off become relevant?', answer: 'During a network partition, when a distributed system cannot guarantee both strong consistency and availability for every request.' }], resources: ['system-primer'] },
  { id: 'sd-api-design', trackId: 'system-design', title: 'API design, pagination & idempotency', level: 'Core', minutes: 26, concept: 'An API is a contract between callers and a service. Define resource names, request/response shapes, validation, status codes, authentication, rate limits and versioning deliberately. Pagination bounds response size; cursor pagination is often more stable than offset pagination when rows change frequently. Idempotency keys make retried create/payment-style operations safer.', example: 'POST /payments with an Idempotency-Key can return the same logical result when a client retries after a timeout. The server records the key and outcome within a defined scope and retention period.', interview: 'Write one success response and at least two failure responses. Clarify pagination order, cursor stability, validation, auth boundaries and duplicate submission behaviour.', pitfalls: ['Exposing unbounded list endpoints.', 'Using offsets over rapidly changing data without considering duplicates or gaps.', 'Accepting an idempotency key without defining scope, expiry and payload mismatch behaviour.'], checks: [{ question: 'Why is cursor pagination often preferred for a changing feed?', answer: 'A stable cursor can continue from an ordering position without large offsets shifting as new records arrive.' }, { question: 'What makes an API operation idempotent?', answer: 'Repeating the same operation does not create additional intended side effects.' }], resources: ['system-primer', 'mdn-web'] },
  { id: 'sd-observability', trackId: 'system-design', title: 'Observability, SLOs & graceful degradation', level: 'Interview depth', minutes: 27, concept: 'Logs record events, metrics summarise behaviour over time and traces connect work across service boundaries. A service-level indicator (SLI) measures an outcome such as latency or successful requests; an SLO sets a target for that indicator. Graceful degradation preserves core functionality when optional dependencies fail.', example: 'A shopping service may keep checkout available while temporarily disabling personalised recommendations. A trace can show whether slow checkout requests spend time in the API, database or payment provider.', interview: 'Name user-facing SLIs, define a measurable SLO window, discuss alerting on symptoms rather than noisy causes, and explain what the service does when a dependency is unavailable.', pitfalls: ['Treating more logs as equivalent to better observability.', 'Setting an SLO without defining numerator, denominator and time window.', 'Letting optional dependencies block a critical user flow.'], checks: [{ question: 'How do traces differ from logs?', answer: 'A distributed trace links timed operations across services; logs are individual event records that may or may not share trace context.' }, { question: 'What is an error budget?', answer: 'The allowed amount of unreliability implied by an SLO over its measurement window.' }], resources: ['system-primer', 'roadmap'] },
  { id: 'apt-data-interpretation', trackId: 'aptitude', title: 'Data interpretation & estimation', level: 'Core', minutes: 22, concept: 'Data interpretation questions test whether you can read charts, tables and percentage changes accurately under time pressure. First identify the unit, base and time period. Estimation helps eliminate implausible options, but calculate exactly when answer choices are close.', example: 'If revenue rises from 80 to 100, the increase is 20 on a base of 80: 25%. It is not 20%, which confuses the absolute change with the percentage change.', interview: 'Read labels and footnotes before calculating. Convert ratios into comparable quantities, check whether the question asks for percentage points or percent change, then sanity-check the magnitude.', pitfalls: ['Using the new value as the denominator for percentage increase.', 'Confusing percentage points with percentage change.', 'Ignoring units or mixing monthly and annual values.'], checks: [{ question: 'A metric rises from 40 to 50. What is the percentage increase?', answer: '10 / 40 × 100 = 25%.' }, { question: 'What is the difference between 5% and 8% as a change in rate?', answer: 'It is an increase of 3 percentage points; relative percentage increase is 60%.' }], resources: ['gfg'] },
  { id: 'apt-number-systems', trackId: 'aptitude', title: 'Number systems, divisibility & remainders', level: 'Interview depth', minutes: 24, concept: 'Number-system problems become easier when you use place value, divisibility rules and modular arithmetic deliberately. A remainder is the residue after division; congruences let you reduce large powers and products before calculating. Check whether the problem expects a non-negative remainder and note the divisor.', example: 'For a number ending in 0, 2, 4, 6 or 8, divisibility by 2 is immediate. To compute a large power modulo m, reduce after each multiplication rather than constructing the full integer.', interview: 'State the modulus, reduce each step and keep residues in the allowed range. Use divisibility shortcuts to eliminate options before doing long arithmetic.', pitfalls: ['Treating a remainder as negative when the question expects 0 through m−1.', 'Applying a divisibility rule to a number written in a different base.', 'Doing huge arithmetic when modular reduction is available.'], checks: [{ question: 'What is 17 mod 5?', answer: '2, because 17 = 3 × 5 + 2.' }, { question: 'Why can you reduce intermediate products modulo m?', answer: 'Congruence is preserved by addition and multiplication, so the final residue remains unchanged.' }], resources: ['gfg'] },

];

