export const questions = [
  { id: 'q-os-1', trackId: 'os', topic: 'Processes & threads', level: 'Warm-up', prompt: 'What is the difference between a process and a thread?', answer: 'A process is an executing program with its own virtual address space and OS-managed resources. Threads are execution paths within a process; they share much of that process state but keep their own stacks and register context. Processes offer stronger isolation; threads usually communicate more cheaply through shared memory.', followUp: 'When would you deliberately use multiple processes instead of threads?', tags: ['process', 'thread', 'fundamentals'] },
  { id: 'q-os-2', trackId: 'os', topic: 'Synchronisation', level: 'Standard', prompt: 'What is a race condition? Give a concrete example.', answer: 'A race condition occurs when the result depends on the timing of concurrent operations. Two threads incrementing the same counter can both read the same old value and overwrite one another’s update. Protect the whole read-modify-write operation with a suitable synchronisation primitive.', followUp: 'Why does making a variable volatile not automatically make counter++ atomic?', tags: ['concurrency', 'mutex'] },
  { id: 'q-os-3', trackId: 'os', topic: 'Deadlocks', level: 'Standard', prompt: 'Explain the four necessary conditions for deadlock.', answer: 'Mutual exclusion, hold-and-wait, no preemption and circular wait. A deadlock requires all four conditions to hold simultaneously. A system can prevent deadlock by ensuring at least one condition cannot occur.', followUp: 'How would you prevent circular wait in a codebase with multiple locks?', tags: ['deadlock', 'locks'] },
  { id: 'q-os-4', trackId: 'os', topic: 'Memory', level: 'Stretch', prompt: 'What happens on a page fault?', answer: 'The CPU’s memory-management hardware traps to the OS because the requested page is not currently mapped as required. The OS checks whether the access is valid, obtains or maps a page if needed, updates translation state and resumes the instruction. Invalid or prohibited accesses result in an error rather than a successful page-in.', followUp: 'What is the role of the TLB during address translation?', tags: ['paging', 'virtual-memory'] },
  { id: 'q-cn-1', trackId: 'cn', topic: 'Transport layer', level: 'Warm-up', prompt: 'Compare TCP and UDP. When would you choose each?', answer: 'TCP provides a reliable, ordered byte stream with retransmission and congestion-control mechanisms. UDP provides datagrams without built-in delivery or ordering guarantees. Choose according to application semantics: correctness and ordering versus latency and application-managed recovery.', followUp: 'How are flow control and congestion control different?', tags: ['tcp', 'udp'] },
  { id: 'q-cn-2', trackId: 'cn', topic: 'Protocols', level: 'Standard', prompt: 'Explain the TCP three-way handshake.', answer: 'The client sends SYN with its initial sequence number. The server responds with SYN-ACK, acknowledging the client and sending its own initial sequence number. The client sends ACK, acknowledging the server. The exchange synchronises sequence state and confirms both directions.', followUp: 'What is the practical difference between FIN and RST?', tags: ['handshake', 'tcp'] },
  { id: 'q-cn-3', trackId: 'cn', topic: 'Web request lifecycle', level: 'Stretch', prompt: 'What happens after you type a URL and press Enter?', answer: 'The browser parses the URL, checks applicable caches and resolves the hostname through DNS. It establishes a connection to the destination, negotiates TLS for HTTPS, sends an HTTP request and processes the response. The browser may then fetch more resources; caches, proxies, CDNs and load balancers can participate along the path.', followUp: 'Where can caching happen in this flow, and what are the risks?', tags: ['dns', 'http', 'tls'] },
  { id: 'q-db-1', trackId: 'dbms', topic: 'Transactions', level: 'Warm-up', prompt: 'Explain ACID properties with a real example.', answer: 'Atomicity: both sides of a transfer happen or neither does. Consistency: constraints and invariants remain valid. Isolation: concurrent transactions do not observe forbidden intermediate states according to the isolation level. Durability: committed changes survive failures under the database’s guarantees.', followUp: 'Can two transactions both be isolated and still execute concurrently?', tags: ['acid', 'transactions'] },
  { id: 'q-db-2', trackId: 'dbms', topic: 'Indexes', level: 'Standard', prompt: 'Why do databases use indexes, and what is the trade-off?', answer: 'Indexes provide an access path that can avoid scanning every row, often using ordered tree structures. They consume storage and must be updated on writes, so extra indexes can slow inserts/updates and increase maintenance cost. The planner may still choose a sequential scan when it is cheaper.', followUp: 'How would you check whether an index is helping a query?', tags: ['index', 'query-plan'] },
  { id: 'q-db-3', trackId: 'dbms', topic: 'SQL', level: 'Standard', prompt: 'What is the difference between WHERE and HAVING?', answer: 'WHERE filters rows before grouping and aggregation. HAVING filters groups after GROUP BY and aggregate computation. A query may use both: WHERE reduces input rows, HAVING filters the resulting groups.', followUp: 'Why can a LEFT JOIN behave like an INNER JOIN after adding a WHERE filter?', tags: ['sql', 'joins'] },
  { id: 'q-db-4', trackId: 'dbms', topic: 'Normalisation', level: 'Stretch', prompt: 'Explain 1NF, 2NF, 3NF and BCNF without memorising one-line definitions.', answer: 'Normalisation removes problematic dependencies and anomalies. 1NF uses atomic attribute values for the chosen relational model. 2NF eliminates partial dependency of non-prime attributes on part of a candidate key. 3NF removes certain transitive dependencies (formally, for every non-trivial X→A, X is a superkey or A is prime). BCNF requires every determinant of a non-trivial dependency to be a superkey.', followUp: 'Can a decomposition be lossless but not dependency-preserving?', tags: ['normalisation', 'functional-dependency'] },
  { id: 'q-oop-1', trackId: 'oops', topic: 'OOP pillars', level: 'Warm-up', prompt: 'Explain the four pillars of OOP with a practical example.', answer: 'Encapsulation protects object state behind methods; abstraction exposes the essential contract; inheritance derives a subtype; polymorphism allows different implementations behind a common type. For example, Checkout can depend on a PaymentMethod interface while CardPayment and UpiPayment implement the payment behaviour differently.', followUp: 'Can you give an example where inheritance is the wrong choice?', tags: ['oop', 'pillars'] },
  { id: 'q-oop-2', trackId: 'oops', topic: 'Dispatch', level: 'Standard', prompt: 'Overloading vs overriding: what decides which method runs?', answer: 'Overloading means same method name with different parameter lists; selection is generally compile-time based on the call signature and language rules. Overriding replaces an inherited instance method implementation; runtime dispatch selects the implementation based on the actual object type.', followUp: 'Can static methods be overridden in Java?', tags: ['overloading', 'overriding'] },
  { id: 'q-oop-3', trackId: 'oops', topic: 'Design', level: 'Stretch', prompt: 'What does “composition over inheritance” mean?', answer: 'Prefer assembling behaviour from collaborating objects when the relationship is has-a or when parts should vary independently. It can reduce tight coupling to a base class and make dependencies easier to substitute and test. Use inheritance when the subtype honours the base type’s behavioural contract.', followUp: 'Give an example of a Strategy pattern implemented using composition.', tags: ['composition', 'design'] },
  { id: 'q-sd-1', trackId: 'system-design', topic: 'Interview structure', level: 'Warm-up', prompt: 'How do you approach an unfamiliar system design question?', answer: 'Clarify the use cases, users and non-functional requirements; estimate scale; define APIs and data; sketch the high-level architecture; then deep-dive into the key bottleneck, consistency choice and failure modes. State assumptions and invite the interviewer to prioritise trade-offs.', followUp: 'What would you clarify before designing a URL shortener?', tags: ['approach', 'requirements'] },
  { id: 'q-sd-2', trackId: 'system-design', topic: 'Scalability', level: 'Standard', prompt: 'What is the difference between vertical and horizontal scaling?', answer: 'Vertical scaling increases resources on one machine. Horizontal scaling adds machines or instances and distributes work. Horizontal scaling can improve capacity and fault tolerance but introduces coordination, partitioning, load balancing and distributed failure concerns.', followUp: 'What makes a service stateful, and why can that complicate horizontal scaling?', tags: ['scaling', 'architecture'] },
  { id: 'q-sd-3', trackId: 'system-design', topic: 'Caching', level: 'Standard', prompt: 'Explain cache-aside and its main failure modes.', answer: 'The application checks the cache first; on a miss it reads the backing store and fills the cache. Challenges include stale data, invalidation, hot keys, stampedes, cold starts and cache outages. A design needs a freshness policy and fallback behaviour.', followUp: 'How would you prevent 10,000 requests from stampeding one expired key?', tags: ['cache', 'reliability'] },
  { id: 'q-sd-4', trackId: 'system-design', topic: 'Reliability', level: 'Stretch', prompt: 'Why are retries and idempotency usually discussed together?', answer: 'Retries recover transient failures, but the original request may have succeeded even when its response was lost. Repeating a non-idempotent side effect can create duplicates. An idempotency key or deduplication record makes repeated delivery safe within a defined scope.', followUp: 'What should happen to a message that fails processing repeatedly?', tags: ['retries', 'idempotency'] },
  { id: 'q-dsa-1', trackId: 'dsa', topic: 'Complexity', level: 'Warm-up', prompt: 'How do you analyse the time complexity of nested loops?', answer: 'Do not count loop nesting alone. Express the total number of iterations as a sum. Two loops each running n times usually produce n² work, but a loop whose inner index advances across the entire input only once may still be linear overall.', followUp: 'What is the complexity of merge sort and why?', tags: ['complexity', 'analysis'] },
  { id: 'q-dsa-2', trackId: 'dsa', topic: 'Binary search', level: 'Standard', prompt: 'What does “binary search on answer” mean?', answer: 'A candidate answer can be tested using a monotonic feasibility predicate. If a value works, all higher or all lower values also work. Binary search finds the boundary rather than a target element, after proving monotonicity and defining a correct interval invariant.', followUp: 'How would you prove the feasibility predicate is monotonic?', tags: ['binary-search', 'patterns'] },
  { id: 'q-dsa-3', trackId: 'dsa', topic: 'Graphs', level: 'Stretch', prompt: 'When would you use BFS, DFS and Dijkstra?', answer: 'BFS explores unweighted graphs by increasing edge distance and gives shortest paths by number of edges. DFS explores deeply and is useful for connectivity, cycle detection and topological-style reasoning. Dijkstra finds shortest paths with non-negative edge weights.', followUp: 'Why is ordinary BFS not sufficient for unequal positive edge weights?', tags: ['graphs', 'traversal'] },
  { id: 'q-apt-1', trackId: 'aptitude', topic: 'Time & work', level: 'Warm-up', prompt: 'A finishes a task in 6 days and B in 12 days. How long together?', answer: 'A’s rate is 1/6 per day and B’s is 1/12. Combined rate = 1/6 + 1/12 = 1/4 of the job per day, so they finish in 4 days.', followUp: 'What if B joins A after A has already worked for 2 days?', tags: ['rates', 'time-work'] },
  { id: 'q-apt-2', trackId: 'aptitude', topic: 'Percentages', level: 'Standard', prompt: 'A value increases by 20% and then decreases by 20%. What is the net change?', answer: 'Multiply the factors: 1.2 × 0.8 = 0.96. The final value is 96% of the original, so it decreases by 4%.', followUp: 'What would happen with +25% followed by −20%?', tags: ['percentages', 'arithmetic'] },
  { id: 'q-hr-1', trackId: 'hr', topic: 'Introduction', level: 'Warm-up', prompt: 'Tell me about yourself.', answer: 'Build a 60–90 second answer around present focus, relevant proof and direction: what you are studying/building, one or two concrete examples of skills or impact, and why this role is the logical next step. Keep personal history brief and do not read your resume aloud.', followUp: 'Which project or technical decision best demonstrates the skill you just mentioned?', tags: ['intro', 'communication'] },
  { id: 'q-hr-2', trackId: 'hr', topic: 'Behavioural', level: 'Standard', prompt: 'Tell me about a time you disagreed with a teammate.', answer: 'Use STAR: Situation (context), Task (your responsibility), Action (how you listened, compared evidence and reached a decision), Result (outcome and learning). Make your own contribution clear without blaming the other person.', followUp: 'What would you do differently now?', tags: ['star', 'teamwork'] },
  { id: 'q-hr-3', trackId: 'hr', topic: 'Motivation', level: 'Standard', prompt: 'Why should we hire you for this role?', answer: 'Connect role requirements to demonstrated evidence. Choose two strengths, give short examples, and explain how you would apply them. Avoid claiming you are the best candidate or giving generic adjectives without proof.', followUp: 'What is one skill you are actively improving?', tags: ['motivation', 'fit'] },
  { id: 'q-project-1', trackId: 'projects', topic: 'Project deep dive', level: 'Standard', prompt: 'Walk me through a project you built end to end.', answer: 'Cover the user/problem, constraints, architecture, data flow, your personal contribution, one difficult technical decision, testing, deployment and what you would change next. Be prepared to draw the system and explain a request from client to storage and back.', followUp: 'What broke during development, and how did you isolate the cause?', tags: ['projects', 'ownership'] },
  { id: 'q-project-2', trackId: 'projects', topic: 'Engineering judgement', level: 'Stretch', prompt: 'What would you redesign if this project had 10× the users?', answer: 'First identify the current bottleneck using evidence rather than guessing. Then discuss likely pressure points—database reads/writes, synchronous work, caching, rate limits, background jobs, observability—and prioritise the lowest-risk change that addresses measured load.', followUp: 'What metric would tell you the redesign worked?', tags: ['scaling', 'trade-offs'] },

  { id: 'q-os-5', trackId: 'os', topic: 'Memory management', level: 'Standard', prompt: 'What happens during a page fault?', answer: 'The CPU detects that the referenced virtual page is not present with the required permissions. Control transfers to the OS, which validates the access, obtains or allocates a page, updates mapping state and resumes the instruction. Invalid access can terminate the process.', followUp: 'Why can too many page faults cause thrashing?', tags: ['paging', 'virtual-memory'] },
  { id: 'q-os-6', trackId: 'os', topic: 'Scheduling', level: 'Stretch', prompt: 'Starvation vs deadlock: how are they different?', answer: 'Deadlock is a set of tasks blocked waiting on one another so none can progress. Starvation occurs when a task is continually denied a resource while other tasks progress. Aging or fair scheduling can reduce starvation; deadlock requires prevention, avoidance, detection or recovery.', followUp: 'Can priority scheduling cause starvation, and how can aging help?', tags: ['scheduling', 'deadlock'] },
  { id: 'q-cn-4', trackId: 'cn', topic: 'TCP', level: 'Standard', prompt: 'What is the purpose of the TCP three-way handshake?', answer: 'It synchronises initial sequence numbers in both directions and confirms that each endpoint can send and receive. SYN, SYN-ACK and ACK establish connection state before application data is exchanged.', followUp: 'Why is a two-way handshake insufficient?', tags: ['tcp', 'handshake'] },
  { id: 'q-cn-5', trackId: 'cn', topic: 'HTTPS', level: 'Standard', prompt: 'What does TLS provide when a browser connects using HTTPS?', answer: 'TLS can authenticate the server using certificates, negotiate cryptographic keys and protect application data in transit with confidentiality and integrity. The exact handshake depends on the TLS version and configuration.', followUp: 'Does HTTPS hide the destination IP address from the network?', tags: ['tls', 'https'] },
  { id: 'q-cn-6', trackId: 'cn', topic: 'Routing', level: 'Stretch', prompt: 'What is the difference between an IP address and a MAC address?', answer: 'An IP address is a logical network-layer address used for routing between networks. A MAC address is a link-layer identifier used to deliver frames on a local link. Routers forward IP packets while replacing the link-layer frame for each hop.', followUp: 'Why does the first Ethernet frame use the gateway MAC for a remote destination?', tags: ['ip', 'mac', 'routing'] },
  { id: 'q-db-5', trackId: 'dbms', topic: 'Isolation', level: 'Stretch', prompt: 'Explain a lost update with a concrete transaction schedule.', answer: 'Two transactions read the same value, independently calculate an update, and then one write overwrites the other. Both may commit, but one logical update is lost. Locking, optimistic version checks or serializable execution can prevent it.', followUp: 'How would you implement an optimistic update with a version column?', tags: ['transactions', 'isolation'] },
  { id: 'q-db-6', trackId: 'dbms', topic: 'SQL', level: 'Standard', prompt: 'What is the difference between RANK, DENSE_RANK and ROW_NUMBER?', answer: 'ROW_NUMBER assigns a unique sequence to each row. RANK gives tied rows the same rank and leaves gaps after ties. DENSE_RANK gives tied rows the same rank without gaps. ORDER BY defines the ranking order.', followUp: 'How would you return the top three salaries per department while keeping ties?', tags: ['sql', 'window-functions'] },
  { id: 'q-oop-4', trackId: 'oops', topic: 'Abstraction', level: 'Standard', prompt: 'Abstract class vs interface: how do you choose?', answer: 'Use an interface for a contract or capability that unrelated types can implement. Use an abstract class when related types share state or partial implementation. Language features differ, so state which language you mean.', followUp: 'Can a Java class implement multiple interfaces but extend only one class?', tags: ['interfaces', 'abstraction'] },
  { id: 'q-oop-5', trackId: 'oops', topic: 'SOLID', level: 'Stretch', prompt: 'Explain dependency inversion with a practical example.', answer: 'High-level policy should depend on abstractions rather than concrete low-level details. An order service can depend on a PaymentGateway contract while a vendor-specific gateway or test double is supplied from outside.', followUp: 'How is dependency inversion related to dependency injection?', tags: ['solid', 'dependency-inversion'] },
  { id: 'q-sd-5', trackId: 'system-design', topic: 'Consistency', level: 'Stretch', prompt: 'What is the practical meaning of eventual consistency?', answer: 'After a write, replicas may temporarily return older data, but under stated assumptions they converge if updates stop and replication succeeds. The design must identify which reads can be stale and what the user sees.', followUp: 'How would you provide read-your-writes for a user who just updated a record?', tags: ['consistency', 'replication'] },
  { id: 'q-sd-6', trackId: 'system-design', topic: 'Partitioning', level: 'Standard', prompt: 'Sharding vs replication: what problem does each solve?', answer: 'Sharding partitions the dataset across nodes to spread storage and workload. Replication keeps copies of the same data on multiple nodes to improve availability or read locality. Systems often use both, but each adds complexity.', followUp: 'What makes a poor shard key?', tags: ['sharding', 'replication'] },
  { id: 'q-sd-7', trackId: 'system-design', topic: 'Estimation', level: 'Standard', prompt: 'How do you make a quick capacity estimate in a design interview?', answer: 'State assumptions, estimate active users and requests per user, derive average and peak requests per second, then estimate data size and bandwidth. Keep units visible and round to powers of ten; the goal is to surface bottlenecks, not pretend estimates are exact.', followUp: 'Why estimate peak traffic separately from average traffic?', tags: ['capacity', 'estimation'] },
  { id: 'q-dsa-4', trackId: 'dsa', topic: 'Dynamic programming', level: 'Stretch', prompt: 'How do you move from recursion to dynamic programming?', answer: 'Identify repeated subproblems, define the state, write the recurrence and base cases, then cache results (memoisation) or evaluate states in dependency order (tabulation). Prove which previous states are needed before reducing memory.', followUp: 'What does dp[i][j] represent in a two-dimensional DP problem?', tags: ['dp', 'recursion'] },
  { id: 'q-dsa-5', trackId: 'dsa', topic: 'Heap', level: 'Standard', prompt: 'When is a heap preferable to sorting?', answer: 'A heap is useful when you repeatedly need the current minimum/maximum or only need top K of N elements. A size-k heap can take O(n log k) time and O(k) space rather than sorting all values in O(n log n).', followUp: 'Which heap root would you keep for the k largest elements?', tags: ['heap', 'top-k'] },
  { id: 'q-apt-3', trackId: 'aptitude', topic: 'Probability', level: 'Standard', prompt: 'Two fair dice are rolled. What is the probability that their sum is 7?', answer: 'There are 36 equally likely ordered outcomes. Six give a sum of 7, so the probability is 6/36 = 1/6.', followUp: 'Why count ordered pairs when rolling two distinguishable dice?', tags: ['probability', 'counting'] },
  { id: 'q-hr-4', trackId: 'hr', topic: 'Failure & learning', level: 'Standard', prompt: 'Tell me about a time something you owned did not go as planned.', answer: 'Choose a real example, explain the goal and your responsibility, identify the signal that something was wrong, describe the corrective action and what changed afterwards. Take ownership without exaggerating the outcome.', followUp: 'What early warning would help you detect the same issue next time?', tags: ['star', 'ownership'] },
  { id: 'q-project-3', trackId: 'projects', topic: 'Testing', level: 'Standard', prompt: 'How did you test your project beyond the happy path?', answer: 'Discuss unit tests for isolated logic, integration tests at boundaries, negative and edge cases, and smoke tests for the deployed path. Explain what the tests assert and what remains untested rather than quoting coverage alone.', followUp: 'Which bug would your current test suite fail to catch?', tags: ['testing', 'quality'] },

];



